/**
 * Central brand configuration.
 *
 * Everything the brand owns that is NOT a colour lives here.
 * Brand colours are defined once in `src/styles/tokens.css` (see that file's
 * "COLOURS" block) so they are never duplicated across components.
 *
 * No secrets, API keys or private credentials belong in this file.
 */

/**
 * Responsive WebP sets for the monogram. `widths` are the exact candidate
 * sizes published in every `srcset` — and the file list generated by
 * `npm run images:optimize` (this is the single source of truth for both).
 */
export const logoAssets = {
  /** Transparent monogram, served as <base>-<width>.webp. */
  light: { base: '/brand/monogram', widths: [72, 144, 288, 432] },
  /** Monogram composited on the ink colour for dark surfaces. */
  onInk: { base: '/brand/monogram-on-ink', widths: [352, 704, 1056] },
} as const;

/** `srcset` value for a logo asset set (width descriptors). */
export const srcsetOf = (asset: { base: string; readonly widths: readonly number[] }): string =>
  asset.widths.map((w) => `${asset.base}-${w}.webp ${w}w`).join(', ');

/** Largest candidate — used as the plain `src` fallback. */
export const primaryOf = (asset: { base: string; readonly widths: readonly number[] }): string =>
  `${asset.base}-${asset.widths[asset.widths.length - 1]}.webp`;

export const brand = {
  name: 'AADHYARNA',

  /**
   * Monogram assets. The artwork masters (public/brand/monogram.webp,
   * monogram-on-ink.webp, monogram-original.jpeg) are never modified —
   * responsive variants are generated from them by
   * `npm run images:optimize`.
   */
  logo: {
    /** Transparent monogram for light surfaces (header, hero, cards). */
    light: primaryOf(logoAssets.light),
    lightSrcset: srcsetOf(logoAssets.light),
    /** Monogram composited on the ink colour for dark surfaces (footer, panels). */
    onInk: primaryOf(logoAssets.onInk),
    onInkSrcset: srcsetOf(logoAssets.onInk),
    /** Display width: `min(100%, 22rem)` in the brand panel, full width below. */
    onInkSizes: '(min-width: 900px) 352px, 88vw',
    /** Untouched copy of the supplied source artwork. */
    source: '/brand/monogram-original.jpeg',
    /** 1200×630 JPEG for Open Graph cards (ivory letterbox, generated). */
    og: '/brand/og-image.jpg',
    favicon: '/favicon.png',
    faviconWebp: '/favicon.webp',
    appleTouchIcon: '/apple-touch-icon.png',
    alt: 'AADHYARNA monogram: four gold curves meeting at a brilliant diamond',
    /** Short alt used where the wordmark is already adjacent. */
    altShort: 'AADHYARNA monogram',
  },

  contact: {
    /**
     * Confirmed business WhatsApp number (owner supplied, Phase 2 §11).
     * `digits` must be international format, no spaces and no leading "+".
     */
    whatsappDisplay: '+39 351 146 5617',
    whatsappDigits: '393511465617',

    /** Awaiting owner confirmation — leave empty until supplied (Phase 2 §16). */
    email: '',
    phone: '',
    addressLine: '',
    city: '',
    country: '',
  },

  /**
   * Social profiles. Empty until supplied.
   * Shape: { label: 'Instagram', href: 'https://…' }
   */
  social: [] as { label: string; href: string }[],
} as const;

/** True only when the owner has supplied a value. */
export const hasContactField = (value: string): boolean => value.trim().length > 0;
